"""Generate src/spec.ts from python-pptx's pptx/spec.py (imported, so values are upstream's).

Usage: python scripts/gen_spec.py src/spec.ts
"""
import json
import sys

from pptx import spec
from pptx.enum.shapes import MSO_AUTO_SHAPE_TYPE

out = [
    "// GENERATED by scripts/gen_spec.py from python-pptx's pptx/spec.py. Do not edit.",
    "// Mappings from the ISO/IEC 29500 spec.",
    'import { MSO_AUTO_SHAPE_TYPE } from "./enum/shapes.js";',
    "",
    f"export const GRAPHIC_DATA_URI_CHART = {json.dumps(spec.GRAPHIC_DATA_URI_CHART)};",
    f"export const GRAPHIC_DATA_URI_OLEOBJ = {json.dumps(spec.GRAPHIC_DATA_URI_OLEOBJ)};",
    f"export const GRAPHIC_DATA_URI_TABLE = {json.dumps(spec.GRAPHIC_DATA_URI_TABLE)};",
    "",
    "/** An adjustment name and its default value, e.g. ['adj1', 16200000]. */",
    "export type AdjustmentValue = readonly [name: string, value: number];",
    "",
    "/** Basename and default adjustments of an autoshape type. */",
    "export interface ShapeSpec {",
    "  readonly basename: string;",
    "  readonly avLst: readonly AdjustmentValue[];",
    "}",
    "",
    "/** {MSO_AUTO_SHAPE_TYPE member: ShapeSpec}, keyed by the member's int value. */",
    "export const autoshapeTypes: ReadonlyMap<number, ShapeSpec> = new Map<number, ShapeSpec>([",
]
for member, d in spec.autoshape_types.items():
    av = ", ".join(f"[{json.dumps(n)}, {v}]" for n, v in d["avLst"])
    out.append(f"  [MSO_AUTO_SHAPE_TYPE.{member.name}.value, {{ basename: {json.dumps(d['basename'])}, avLst: [{av}] }}],")
out.append("]);")
open(sys.argv[1], "w", encoding="utf-8", newline="\n").write("\n".join(out) + "\n")
